function demoMain(idx,label){
  var plans=[["rename foo->bar",["a.js","b.js","c.js"]],["upgrade dep v1->v2",["pkg.json","lock"]],["move util/",["x.js","y.js","z.js","w.js"]]];
  var p=plans[idx%plans.length];
  return "["+label+"] plan '"+p[0]+"' touches "+p[1].length+" files: "+p[1].join(", ");
}

